package com.yeyamo_mobile.api.moderation_trust_service.infrastructure.persistence;import java.util.Optional;import org.springframework.stereotype.Component;import com.yeyamo_mobile.api.moderation_trust_service.domain.model.TrustScore;import com.yeyamo_mobile.api.moderation_trust_service.domain.port.TrustScoreRepository;
@Component public class JpaTrustScoreAdapter implements TrustScoreRepository{private final SpringTrustScoreRepository repo;public JpaTrustScoreAdapter(SpringTrustScoreRepository r){repo=r;}public TrustScore save(TrustScore s){var e=new TrustScoreEntity();e.setSubjectId(s.getSubjectId());e.setScore(s.getScore());e.setApprovedReports(s.getApprovedReports());e.setRejectedReports(s.getRejectedReports());e.setUpdatedAt(s.getUpdatedAt());e.setVersion(s.getVersion());return domain(repo.save(e));}public Optional<TrustScore>findById(String id){return repo.findById(id).map(this::domain);}private TrustScore domain(TrustScoreEntity e){var s=new TrustScore();s.setSubjectId(e.getSubjectId());s.setScore(e.getScore());s.setApprovedReports(e.getApprovedReports());s.setRejectedReports(e.getRejectedReports());s.setUpdatedAt(e.getUpdatedAt());s.setVersion(e.getVersion());return s;}}
